import{_ as t,o as a,c as o,aF as r}from"./chunks/framework.CNkxH4QO.js";const b=JSON.parse('{"title":"krawler-weatherlink","description":"A Krawler based job to download data from the WeatherLink weather station network.","frontmatter":{"title":"krawler-weatherlink","description":"A Krawler based job to download data from the WeatherLink weather station network."},"headers":[],"relativePath":"packages/krawler-weatherlink/index.md","filePath":"packages/krawler-weatherlink/index.md"}'),d={name:"packages/krawler-weatherlink/index.md"};function i(s,e,n,l,c,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="krawler-weatherlink" tabindex="-1">krawler-weatherlink <a class="header-anchor" href="#krawler-weatherlink" aria-label="Permalink to &quot;krawler-weatherlink&quot;">​</a></h1><p><em>A Krawler based job to download data from <a href="https://weatherlink.github.io/" target="_blank" rel="noreferrer">WeatherLink V2 API</a>.</em></p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The <strong>krawler-weatherlink</strong> jobs scrape all sort of data from sensors connected to stations. The data are stored in a <a href="https://www.mongodb.com/" target="_blank" rel="noreferrer">MongoDB</a> database and more precisely in 2 collections:</p><ul><li>the <code>observations</code> collection stores the observed data from the sensors, more information <a href="https://weatherlink.github.io/v2-api/data-structure-types" target="_blank" rel="noreferrer">here</a></li><li>the <code>stations</code> collection stores the data of the stations</li></ul><div class="caution custom-block github-alert"><p class="custom-block-title">CAUTION</p><p>This service only supports <strong>Data Structure <a href="https://weatherlink.github.io/v2-api/data-structure-types" target="_blank" rel="noreferrer">Type 23</a></strong>. Using other data types result in storage issues.</p></div><p>The project consists in 2 jobs:</p><ul><li>the <code>stations</code> job scrapes the stations data associated to your account, according a specific cron expression. By default every day at midnight.</li><li>the <code>observations</code> job scrapes the last (current) observation of the stations above according a specific cron expression. By default every 5 minutes.</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>The data retrieved and frequency at which they are retrieved are limited by your relationship with the station and subscription, see more <a href="https://weatherlink.github.io/v2-api/data-permissions" target="_blank" rel="noreferrer">here</a>.</p></div><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><h3 id="stations" tabindex="-1">Stations <a class="header-anchor" href="#stations" aria-label="Permalink to &quot;Stations&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>DB_URL</code></td><td>The database URL. The default value is <code>mongodb://127.0.0.1:27017/weatherlink</code></td></tr><tr><td><code>STN_COLLECTION</code></td><td>The collection name to store the stations data. The default value is <code>weatherlink-stations</code>.</td></tr><tr><td><code>API_KEY</code></td><td>The WeatherLink API key for authentication.</td></tr><tr><td><code>API_SECRET</code></td><td>The WeatherLink API secret to sign requests.</td></tr><tr><td><code>DEBUG</code></td><td>Enables debug output. Set it to <code>krawler*</code> to enable full output. By default it is undefined.</td></tr></tbody></table><h3 id="observations" tabindex="-1">Observations <a class="header-anchor" href="#observations" aria-label="Permalink to &quot;Observations&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>DB_URL</code></td><td>The database URL. The default value is <code>mongodb://127.0.0.1:27017/weatherlink</code></td></tr><tr><td><code>STN_COLLECTION</code></td><td>The collection name from which to retrieve the stations data. The default value is <code>weatherlink-stations</code>.</td></tr><tr><td><code>OBS_COLLECTION</code></td><td>The collection name to store the observations data. The default value is <code>weatherlink-observations</code>.</td></tr><tr><td><code>TTL</code></td><td>The observations data time to live. It must be expressed in seconds and the default value is <code>604 800</code> (7 days)</td></tr><tr><td><code>API_KEY</code></td><td>The WeatherLink API key for authentication.</td></tr><tr><td><code>API_SECRET</code></td><td>The WeatherLink API secret to sign requests.</td></tr><tr><td><code>DATA_TYPE</code></td><td>The <a href="https://weatherlink.github.io/v2-api/data-structure-types" target="_blank" rel="noreferrer">data types</a> to retrieve (e.g <code>1,11,13,4,15</code>). The default value is <code>everything (1 to 27)</code>.</td></tr><tr><td><code>TIMEOUT</code></td><td>The maximum duration of the job. It must be in milliseconds and the default value is <code>1 800 000</code> (30 minutes).</td></tr><tr><td><code>DEBUG</code></td><td>Enables debug output. Set it to <code>krawler*</code> to enable full output. By default it is undefined.</td></tr></tbody></table><h2 id="deployment" tabindex="-1">Deployment <a class="header-anchor" href="#deployment" aria-label="Permalink to &quot;Deployment&quot;">​</a></h2><p>We personally use <a href="https://kalisio.github.io/kargo/" target="_blank" rel="noreferrer">Kargo</a> to deploy the service.</p>',16)])])}const p=t(d,[["render",i]]);export{b as __pageData,p as default};
